const SpeciesForms=require('../js/modules/character-species-forms');
function speciesForm(race,level=5,extra={}){const d=character({race,edition:R.races[race].edition||'2014',raceFeature:'red',dragon:'red',...extra});d.hpCurrent=10;return {d,level,context:{level,confirmed:true,onStone:true}};}
function withSpeciesExperience(task){const vm=require('node:vm'),fs=require('node:fs'),{createRequire}=require('node:module'),file=require.resolve('../js/modules/character-adobe-engine'),context={require:createRequire(file),CharacterSheetModel:{...M,__adobeIntegrated:true},CharacterProgression:require('../js/modules/character-progression'),CharacterSubclassPlanning:require('../js/modules/character-subclass-planning')};vm.createContext(context);vm.runInContext(fs.readFileSync(file,'utf8'),context);const previous=global.CharacterAdobeEngine;global.CharacterAdobeEngine=context.CharacterAdobeEngine;try{task();}finally{if(previous===undefined)delete global.CharacterAdobeEngine;else global.CharacterAdobeEngine=previous;}}
test('species counters and activation gates use actual XP level instead of a stale identity, preserving the manual-level mode',()=>withSpeciesExperience(()=>{
 for(const [race,edition,option]of [['dragonborn-2024','2024',''],['aasimar-2024','2024','wings'],['shadar-kai-mpmm','2014','']]){const {d}=speciesForm(race,1);d.adobe={useExperience:true,classLevels:[{classId:'fighter',level:20}]};d.experience=355000;assert.equal(SpeciesResources.effectiveLevel(d,1),20);assert.equal(SpeciesForms.state(d,{level:1}).available,true);assert.equal(SpeciesForms.activate(d,{level:1,confirmed:true,revelation:option}),true);assert.equal(SpeciesForms.state(d,{level:1}).resource.level,20);if(race==='shadar-kai-mpmm'){assert.equal(SpeciesForms.state(d,{level:1}).active,true);assert.equal(SpeciesForms.state(d,{level:1}).resource.max,6);}else if(race==='aasimar-2024'){assert.equal(SpeciesForms.state(d,{level:1}).rider.amount,6);SpeciesForms.recordRider(d,{level:1,confirmed:true});F.resetClassResources(d,'turn',{level:1});assert.equal(SpeciesForms.state(d,{level:1}).active,true);assert.equal(SpeciesForms.state(d,{level:1}).rider.used,0);}
  d.adobe.useExperience=false;assert.equal(SpeciesResources.effectiveLevel(d,1),1);if(race!=='shadar-kai-mpmm')assert.equal(SpeciesForms.state(d,{level:1}).available,false);
 }
}));
test('lowering XP cannot leave an unlocked species form or regain an already spent use when XP rises again',()=>withSpeciesExperience(()=>{
 const {d}=speciesForm('aasimar-2024',1);d.adobe={useExperience:true};d.experience=355000;assert.equal(SpeciesForms.activate(d,{level:1,confirmed:true,revelation:'wings'}),true);d.experience=0;SpeciesForms.endInvalid(d,{level:1});assert.equal(SpeciesForms.state(d,{level:1}).rawActive,false);d.experience=355000;assert.equal(SpeciesForms.state(d,{level:1}).active,false);assert.equal(SpeciesForms.state(d,{level:1}).resource.used,1);assert.equal(SpeciesForms.activate(d,{level:1,confirmed:true,revelation:'wings'}),false);
 const {d:small}=speciesForm('goblin-mpmm',1);small.adobe={useExperience:true};small.experience=355000;for(let turn=0;turn<6;turn++){assert.equal(F.changeClassResource(small,'species-fury',1,{level:1}),true);SpeciesResources.newTurn(small,'species-fury',{level:1});}assert.equal(F.changeClassResource(small,'species-fury',1,{level:1}),false);assert.equal(SpeciesResources.resources(small,{level:1})[0].max,6);
}));
test('temporary species effects require their source, unlock, action conditions and an atomic use/activation write',()=>{
 assert.equal(Object.keys(SpeciesForms.definitions).length,8);
 for(const race of ['shadar-kai-mpmm','dwarf-2024','goliath-2024','dragonborn-2024','gem-dragonborn-ftd','chromatic-dragonborn-ftd']){
  const {d,context}=speciesForm(race),s=SpeciesForms.state(d,context);assert.equal(s.canActivate,true,race);assert.equal(F.changeClassResource(d,s.resource.id,1,context),false,'a counter edit cannot bypass activation');assert.equal(SpeciesForms.activate(d,{...context,confirmed:false}),false);assert.equal(SpeciesForms.activate(d,context),true);assert.equal(M.derive(d,5).speciesForm.active,true);assert.equal(SpeciesForms.state(d,context).resource.used,1);
  const saved=JSON.parse(JSON.stringify(d));assert.equal(M.derive(saved,5).speciesForm.active,true);SpeciesForms.end(saved,context);assert.equal(M.derive(saved,5).speciesForm.active,false);assert.equal(SpeciesForms.state(saved,context).resource.used,1);assert.equal(SpeciesForms.undo(saved,context),true);assert.equal(SpeciesForms.state(saved,context).resource.used,0);
 }
 const {d,context}=speciesForm('dragonborn-2024',4);assert.equal(SpeciesForms.activate(d,context),false);d.build.edition='2014';assert.equal(SpeciesForms.activate(d,{...context,level:20}),false);
 const full=speciesForm('dwarf-2024');full.d.adobe={classFeatureChoices:Object.fromEntries(Array.from({length:98},(_,i)=>['retained:'+i,['0']]))};const before=JSON.stringify(full.d);assert.equal(SpeciesForms.activate(full.d,full.context),false);assert.equal(JSON.stringify(full.d),before,'Stonecunning needs three ledger keys and cannot spend only part of its activation');
});
test('Aasimar Revelation follows character level, fixed legacy Origin choices or a revised activation choice, and atomically spends three keys',()=>{
 for(const [race,choices]of [['aasimar-mpmm',['soul','consumption','shroud']],['aasimar-2024',['wings','radiance','shroud']]])for(const level of [1,2,3,5,11,20])for(const option of choices){const {d,context}=speciesForm(race,level,{raceFeature:option});d.adobe={classLevels:[{classId:'fighter',level:1},{classId:'wizard',level:20}]};assert.equal(SpeciesForms.activate(d,{...context,revelation:option}),level>=3);if(level>=3){const s=SpeciesForms.state(d,context);assert.equal(s.option,option);assert.equal(s.resource.used,1);assert.equal(s.rider.amount,Math.ceil(level/4)+1);assert.equal(SpeciesForms.activate(d,{...context,revelation:option}),false);}}
 for(const option of ['',null,'constructor','__proto__','soul']){const {d,context}=speciesForm('aasimar-2024');const before=JSON.stringify(d);assert.equal(SpeciesForms.activate(d,{...context,revelation:option}),false);assert.equal(JSON.stringify(d),before);}
 const {d,context}=speciesForm('aasimar-mpmm',5,{raceFeature:'soul'});assert.equal(SpeciesForms.activate(d,{...context,revelation:'shroud'}),false);d.adobe={classFeatureChoices:Object.fromEntries(Array.from({length:98},(_,i)=>['retained:'+i,['0']]))};const before=JSON.stringify(d);assert.equal(SpeciesForms.activate(d,context),false);assert.equal(JSON.stringify(d),before);d.build.edition='2024';assert.equal(SpeciesForms.activate(d,context),false);
});
