test('Toll the Dead requires an explicit target condition and scales each die from total character level in both editions',()=>{
 for(const edition of ['2014','2024'])for(const [level,count]of [[1,1],[4,1],[5,2],[11,3],[17,4],[20,4]])for(const effect of ['full-health','wounded']){const {d,row}=spellEffect('Toll the Dead',edition,effect,0,level);assert.equal(row.damage,count+(effect==='wounded'?'d12':'d8')+' necrotic');assert.match(row.hit,/WISDOM DC/);assert.equal(row.proficient,false);assert.match(row.paperName,effect==='wounded'?/Wounded/:/Full HP/);assert.equal(M.derive(JSON.parse(JSON.stringify(d)),level).actions[0].damage,row.damage);}
 const empty=spellEffect('Toll the Dead','2024','');assert.equal(empty.row.available,false);assert.match(empty.row.notes.join(' '),/target condition/);empty.d.actions[0].effect='not-a-real-effect';assert.equal(M.derive(empty.d,4).actions[0].available,false);
});
test('Witch Bolt separates initial hit scaling from its non-scaling automatic ongoing phase and edition-specific action cost',()=>{
 for(const edition of ['2014','2024'])for(const slot of [1,3,9]){const initial=spellEffect('Witch Bolt',edition,'initial',slot,20).row,ongoing=spellEffect('Witch Bolt',edition,'ongoing',slot,20).row;assert.equal(initial.damage,(slot+(edition==='2024'?1:0))+'d12 lightning');assert.equal(initial.proficient,true);assert.match(initial.hit,/^\+/);assert.equal(ongoing.damage,'1d12 lightning');assert.equal(ongoing.paperHit,'Auto');assert.equal(ongoing.proficient,false);assert.match(ongoing.hit,/no attack roll or save/);assert.match(ongoing.notes.join(' '),edition==='2024'?/Bonus Action.*even if the initial attack missed/:/successful initial hit.*Action/);assert.doesNotMatch(ongoing.notes.join(' '),/Upcast effects are not automated/);}
});
test('Hunger of Hadar keeps Cold start and Acid end events separate and assigns revised upcast dice to one component',()=>{
 for(const edition of ['2014','2024']){const {d,spell}=spellEffect('Hunger of Hadar',edition,'',5,9);for(const effect of spell.combat.effects){d.actions[0].effect=effect.id;const row=M.derive(d,9).actions[0],cold=effect.id.startsWith('start'),boost=edition==='2024'&&(cold?effect.id.endsWith('cold'):effect.id.endsWith('acid'));assert.equal(row.damage,(boost?'4d6':'2d6')+(cold?' cold':' acid'));assert.equal(row.hit.startsWith('Automatic'),cold);assert.equal(row.hit.startsWith('DEXTERITY DC'),!cold);assert.equal(row.proficient,false);assert.match(row.notes.join(' '),/only this target-turn event/);if(edition==='2024')assert.match(row.notes.join(' '),/allocation consistent/);}}
});
test('spell effect choices survive normalization, cannot move to unrelated spells and retain class-access boundaries',()=>{
 const {d,spell}=spellEffect('Witch Bolt','2024','ongoing',3,5);const snapshot=JSON.parse(JSON.stringify(d));assert.equal(M.normalize(snapshot).actions[0].effect,'ongoing');assert.equal(M.derive(snapshot,5).actions[0].damage,'1d12 lightning');const bolt=Catalog.data.spells.find(row=>row.name==='Fire Bolt'&&row.edition==='2024');d.spells=[{...Catalog.spellRow(bolt),classId:'additional'}];d.actions[0].ref=bolt.id+'::additional';assert.equal(M.derive(d,5).actions[0].available,false,'an ongoing choice must not suppress Fire Bolt attacks');
 d.spells=[{...Catalog.spellRow(spell),classId:'wizard'}];d.actions[0].ref=spell.id+'::wizard';assert.equal(M.derive(d,5).actions[0].available,false,'the missing Wizard class disables its conditional action too');
});
test('Destructive Wave combines Thunder with exactly one chosen second type and retains the same save without invented upcast dice',()=>{
 for(const edition of ['2014','2024'])for(const kind of ['radiant','necrotic'])for(const slot of [5,7,9]){const {d,row}=spellEffect('Destructive Wave',edition,kind,slot,20),before=JSON.stringify(d);assert.equal(row.damage,'5d6 thunder + 5d6 '+kind);assert.equal(row.damageDice,'5d6+5d6');assert.equal(row.damageType,'thunder / '+kind);assert.match(row.hit,/CONSTITUTION DC/);assert.equal(row.proficient,false);assert.match(row.notes.join(' '),/success halves both components without Prone/);assert.doesNotMatch(row.notes.join(' '),/Upcast effects are not automated/);assert.equal(JSON.stringify(d),before);}
 assert.equal(spellEffect('Destructive Wave','2024','').row.available,false);assert.equal(spellEffect('Destructive Wave','2014','fire').row.available,false);
 const volley=spellEffect('Conjure Volley','2014','',9,20).row;assert.equal(volley.damage,'8d8 bludgeoning / piercing / slashing');assert.match(volley.hit,/DEXTERITY DC/);assert.match(volley.notes.join(' '),/one damage type.*every creature/);
});
test('Fire Shield retaliation has no attack roll, grants no permanent resistance, and uses only the selected shield’s damage',()=>{
 for(const edition of ['2014','2024'])for(const kind of ['fire','cold']){const {d,row}=spellEffect('Fire Shield',edition,kind,9,20);assert.equal(row.damage,'2d8 '+kind);assert.equal(row.hit,'Automatic · no attack roll or save');assert.equal(row.paperHit,'Auto');assert.equal(row.proficient,false);assert.match(row.notes.join(' '),/within 5 ft.*melee attack/);assert.match(row.notes.join(' '),kind==='fire'?/resolve Cold resistance/:/resolve Fire resistance/);assert.equal(M.derive(d,20).effects.resistances.length,0,'an attack reference cannot activate a defensive spell');assert.equal(M.derive(JSON.parse(JSON.stringify(d)),20).actions[0].damage,row.damage);}
 assert.equal(spellEffect('Fire Shield','2024','').row.available,false,'never treat the target’s triggering melee attack as the caster’s own spell attack');
});
test('Enervation follows its exact source’s initial/success/ongoing dice, action costs and different upcasting',()=>{
 for(const slot of [5,6,9]){const old=spellEffect('Enervation','2014','initial-failed',slot,20).row,success=spellEffect('Enervation','2014','initial-success',slot,20).row,ongoing=spellEffect('Enervation','2014','ongoing',slot,20).row,modern=spellEffect('Enervation','2024','initial',slot,20).row,next=spellEffect('Enervation','2024','ongoing',slot,20).row;assert.equal(old.damage,(4+slot-5)+'d8 necrotic');assert.equal(success.damage,(2+slot-5)+'d8 necrotic');assert.match(success.notes.join(' '),/without halving it again/);assert.equal(ongoing.damage,old.damage);assert.equal(ongoing.paperHit,'Auto');assert.match(ongoing.notes.join(' '),/spend your Action.*anything else ends/);assert.equal(modern.damage,(6+slot-5)+'d8 necrotic');assert.equal(next.damage,'2d8 necrotic');assert.equal(next.paperHit,'Auto');assert.match(next.notes.join(' '),/Bonus Action.*does not increase/);assert.match(next.notes.join(' '),/half the Necrotic damage actually taken/);}
 assert.equal(spellEffect('Enervation','2024','initial-failed',5,20).row.available,false);assert.equal(spellEffect('Enervation','2014','initial',5,20).row.available,false);
});
test('Immolation keeps repeated successful saves damage-free and Bones of the Earth separates the crushing event from the lifting save',()=>{
 for(const slot of [5,7,9]){const first=spellEffect('Immolation','2014','initial',slot,20).row,later=spellEffect('Immolation','2014','ongoing',slot,20).row;assert.equal(first.damage,'8d6 fire');assert.equal(later.damage,'4d6 fire');assert.match(first.hit,/DEXTERITY DC/);assert.match(later.notes.join(' '),/success deals no damage and ends/);}
 for(const slot of [6,7,9]){const {d,spell,row}=spellEffect('Bones of the Earth','2014','crush',slot,20),before=JSON.stringify(d);assert.equal(row.damage,'6d6 bludgeoning');assert.equal(row.paperHit,'Auto');assert.equal(spell.save,'DEXTERITY','the list still records the initial lifting save');assert.match(row.notes.join(' '),new RegExp('Creates '+(6+2*(slot-6))+' stone pillars'));assert.match(row.notes.join(' '),/not the initial Dexterity save/);assert.equal(JSON.stringify(d),before);}
});
test('Hail of Thorns separates burst and weapon damage and applies the 6d10 ceiling only to its legacy source',()=>{
 for(const edition of ['2014','2024'])for(const slot of [1,3,6,7,9]){const {d,spell,row}=spellEffect('Hail of Thorns',edition,'',slot,20),before=JSON.stringify(d);assert.equal(row.damage,(edition==='2014'?Math.min(6,slot):slot)+'d10 piercing');assert.match(row.hit,/DEXTERITY DC/);assert.equal(row.proficient,false);assert.equal(row.range,'5-ft burst at hit target');assert.match(row.notes.join(' '),/weapon hit’s own damage separate/);assert.match(row.notes.join(' '),edition==='2014'?/before a later hit.*Damage stops at 6d10/:/immediately after the hit.*no Concentration or 6d10 damage ceiling/);assert.equal(JSON.stringify(d),before);const facts=require('../js/modules/character-spell-summaries').facts(spell);assert.match(facts.scaling,edition==='2014'?/maximum 6d10/:/no 6d10 ceiling/);}
});
test('Ensnaring Strike’s turn-start damage is automatic and separate from its initial save and edition-specific escape check',()=>{
 for(const edition of ['2014','2024'])for(const slot of [1,4,9]){const {d,spell,row}=spellEffect('Ensnaring Strike',edition,'ongoing',slot,20);assert.equal(spell.save,'STRENGTH');assert.equal(row.damage,slot+'d6 piercing');assert.equal(row.paperHit,'Auto');assert.equal(row.proficient,false);assert.match(row.notes.join(' '),/Setup saving throw: STRENGTH DC 17/);assert.match(row.notes.join(' '),edition==='2014'?/Escape Strength check: DC 17/:/Escape Strength \(Athletics\) check: DC 17/);assert.match(row.notes.join(' '),/no new save/);assert.equal(M.derive(JSON.parse(JSON.stringify(d)),20).actions[0].damage,row.damage);}
 assert.equal(spellEffect('Ensnaring Strike','2024','').row.available,false);
});
test('Glyph of Warding requires one inscription type and never combines all five explosions or grants a stored spell',()=>{
 for(const edition of ['2014','2024'])for(const type of ['acid','cold','fire','lightning','thunder'])for(const slot of [3,6,9]){const {d,spell,row}=spellEffect('Glyph of Warding',edition,type,slot,20),before=JSON.stringify(d);assert.equal(row.damage,(5+slot-3)+'d8 '+type);assert.equal(row.damageType,type);assert.match(row.hit,/DEXTERITY DC/);assert.equal(row.range,'20-ft-radius sphere');assert.match(row.notes.join(' '),/choose the damage type when inscribing/);assert.match(row.notes.join(' '),/stored spell separately/);assert.equal(d.spells.length,1);assert.equal(JSON.stringify(d),before);assert.match(require('../js/modules/character-spell-summaries').facts(spell).damage,/Acid\/Cold\/Fire\/Lightning\/Thunder/);}
 assert.equal(spellEffect('Glyph of Warding','2024','').row.available,false);assert.equal(spellEffect('Glyph of Warding','2014','necrotic').row.available,false);
});
