 for(const slot of [4,6,9]){const {spell,row}=spellEffect('Grasping Vine','2024','',slot,20);assert.equal(spell.range,'60 feet');assert.equal(row.range,'30 ft from vine');assert.equal(row.damage,'4d8 bludgeoning');assert.equal(row.proficient,true);assert.match(row.notes.join(' '),/Grapple escape: DC 17/);assert.match(row.notes.join(' '),/without increasing damage per hit/);}
 for(const slot of [5,7,9]){const {row}=spellEffect("Jallarzi's Storm of Radiance",'2024','',slot,20);assert.equal(row.damage,(2+slot-5)+'d10 radiant + '+(2+slot-5)+'d10 thunder');assert.equal(row.damageType,'radiant / thunder');assert.match(row.hit,/CONSTITUTION DC/);assert.match(row.notes.join(' '),/at most once per creature per turn/);assert.match(row.notes.join(' '),/Verbal spellcasting/);}
 const old=spellEffect('Grasping Vine','2014','',9,20).row;assert.equal(old.damage,'See spell effect','legacy vine has no damage dice to borrow from revised vine');
