test('Elemental Weapon keeps each type and exact capped slot bands, without adding its attack bonus to damage or spell attacks',()=>{
 for(const source of ['PHB','XPHB']){const s=Catalog.rawData.spells.find(s=>s.name==='Elemental Weapon'&&s.source===source),d=character({classId:'paladin',edition:s.edition});d.spells=[{...Catalog.spellRow(s),classId:'additional'}];for(const effect of ['acid','cold','fire','lightning','thunder'])for(const [slot,dice,bonus]of [[3,1,1],[4,1,1],[5,2,2],[6,2,2],[7,3,3],[8,3,3],[9,3,3]]){d.actions=[{kind:'spell',ref:s.id+'::additional',slot,effect}];const before=JSON.stringify(d),row=M.derive(d,20).actions[0];assert.equal(row.damage,dice+'d4 '+effect);assert.equal(row.hit,'Automatic · no attack roll or save');assert.equal(row.damageDice,dice+'d4');assert.ok(row.notes.includes('This slot’s enchanted-weapon attack-roll bonus: +'+bonus+'. Apply to that weapon’s actual attack, not to damage or the caster’s spell attacks.'));assert.match(row.notes.join(' '),/nonmagical weapon.*does not enchant equipment/);assert.equal(JSON.stringify(d),before);}for(const effect of [undefined,'poison','constructor']){d.actions=[{kind:'spell',ref:s.id+'::additional',effect}];assert.equal(M.derive(d,20).actions[0].available,false);}}
});
test('Flame Arrows upcasts only affected quiver draws, counting misses without creating ammunition or increasing hit dice',()=>{
 const s=Catalog.rawData.spells.find(s=>s.name==='Flame Arrows'&&s.source==='XGE'),d=character({classId:'ranger'});d.spells=[{...Catalog.spellRow(s),classId:'additional'}];for(const slot of [3,4,7,9]){d.actions=[{kind:'spell',ref:s.id+'::additional',slot}];const before=JSON.stringify(d),row=M.derive(d,20).actions[0];assert.equal(row.damage,'1d6 fire');assert.equal(row.paperHit,'Auto');assert.equal(row.range,'Quiver ammunition hit');assert.ok(row.notes.includes('This slot affects up to '+(12+2*(slot-3))+' arrows or bolts drawn from the affected quiver. Track actual draws; it creates no ammunition.'));assert.match(row.notes.join(' '),/A miss adds none.*after a hit or miss.*Higher slots increase affected ammunition/);assert.doesNotMatch(row.notes.join(' '),/Creates|Upcast effects are not automated/);assert.equal(JSON.stringify(d),before);}
});
test('Zephyr Strike separates once-per-casting own-turn damage from its hit-or-miss turn-limited walking boost',()=>{
 const s=Catalog.rawData.spells.find(s=>s.name==='Zephyr Strike'&&s.source==='XGE'),d=character({classId:'ranger'});d.spells=[{...Catalog.spellRow(s),classId:'additional'}];const beforeSpeed=M.derive(d,20).speed;for(const slot of [1,5,9])for(const effect of ['boosted-hit','movement']){d.actions=[{kind:'spell',ref:s.id+'::additional',slot,effect}];const before=JSON.stringify(d),r=M.derive(d,20),row=r.actions[0];assert.equal(row.available,true);assert.equal(r.speed,beforeSpeed);assert.match(row.notes.join(' '),/one weapon attack roll on your own turn.*once per casting, not once per turn/);if(effect==='boosted-hit'){assert.equal(row.damage,'1d8 force');assert.equal(row.paperHit,'Auto');assert.match(row.notes.join(' '),/A miss adds no extra damage/);}else{assert.equal(row.damage,'See spell effect');assert.equal(row.hit,'Effect');assert.equal(row.damageType,'');assert.match(row.notes.join(' '),/whether it hits or misses.*30 ft until the end of that turn.*does not last for the whole spell/);}assert.equal(JSON.stringify(d),before);}for(const effect of [undefined,'all-hits','constructor']){d.actions[0].effect=effect;assert.equal(M.derive(d,20).actions[0].available,false);}
});
